#!/usr/bin/env python3
"""The check for versionadded/seed. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('from tally.text import title_case\nassert title_case("the art of war") == "The Art of War"\nassert title_case("salt and pepper") == "Salt and Pepper"', env=None))

    import ast
    tree = ast.parse(ws.read('tally/text.py') or "pass")
    fn = next((n for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef)) and n.name == 'title_case'), None)
    doc = (ast.get_docstring(fn) or "") if fn else ""
    marked = re.search(r"\.\. versionadded:: 0\.10(?![\d.])", doc) is not None
    ws.signals["followed"] = marked
    ws.check("rule: title_case's docstring says '.. versionadded:: 0.10'", marked, repr(doc[-300:]))


if __name__ == "__main__":
    main(check)
